    "context": "Para encerrar definitivamente qualquer dúvida remanescente sobre a legitimidade da liderança de Arão depois da rebelião de Corá, Deus realiza o milagre da vara de Arão florescendo, confirmando de forma inconfundível sua escolha sacerdotal. A vara de Arão floresce como sinal para encerrar uma disputa. A vida que brota de madeira seca se torna uma resposta mais silenciosa do que a rebelião que a precedeu.",
